// doc_view_metrics: exact per-camera visibility measurements through the SAME display mesh,
// perspective projection, frustum/section clipping and depth rule as doc_render_view — the
// shot planner's measured input. See contracts/worker_rpc.md "doc_view_metrics".
json doc_view_metrics(const nlohmann::json& params) {
    const auto t_start = std::chrono::steady_clock::now();
    auto refuse = [](const std::string& code, const std::string& reason) {
        return json{{"ok", false}, {"code", code}, {"reason", reason}};
    };
    try {
        if (!params.is_object()) return refuse("params_invalid", "params must be an object");
        const auto doc_it = params.find("doc_id");
        if (doc_it == params.end() || !doc_it->is_string())
            return refuse("doc_id_invalid", "doc_id must be a string");
        const std::string doc_id = doc_it->get<std::string>();

        int size[2] = {192, 144};
        const char* size_keys[2] = {"width", "height"};
        for (int i = 0; i < 2; ++i) {
            const auto it = params.find(size_keys[i]);
            if (it == params.end() || it->is_null()) continue;
            if (!it->is_number_integer())
                return refuse("image_size_invalid", std::string(size_keys[i]) +
                                                        " must be an integer");
            const long long raw = it->is_number_unsigned()
                                      ? (long long)std::min<unsigned long long>(
                                            it->get<unsigned long long>(), 1024ULL)
                                      : it->get<long long>();
            size[i] = (int)std::max(32LL, std::min(raw, 1024LL));
        }
        const int W = size[0], H = size[1];

        const auto cams_it = params.find("cameras");
        if (cams_it == params.end() || !cams_it->is_array() || cams_it->empty())
            return refuse("cameras_invalid", "cameras must be a non-empty array of camera_pose.v1");
        const json& cams = *cams_it;
        constexpr size_t kMaxCameras = 4096;
        if (cams.size() > kMaxCameras)
            return refuse("cameras_too_many",
                          "at most " + std::to_string(kMaxCameras) + " cameras per call");
        std::vector<PerspectiveCamera> cameras;
        cameras.reserve(cams.size());
        for (size_t i = 0; i < cams.size(); ++i) {
            const ResolvedView rv = resolve_view_spec(json{{"camera", cams[i]}});
            if (!rv.refusal_code.empty() || !rv.camera) {
                json out = refuse(rv.refusal_code.empty() ? "camera_invalid" : rv.refusal_code,
                                  "cameras[" + std::to_string(i) + "]: " + rv.refusal_reason);
                out["camera_index"] = (long)i;
                return out;
            }
            cameras.push_back(*rv.camera);
        }

        std::string reason;
        SectionSpec default_section;
        bool has_default_section = false;
        if (params.contains("section")) {
            const int parsed = parse_section_spec(params.at("section"), default_section, reason);
            if (parsed < 0) return refuse("section_invalid", "section: " + reason);
            has_default_section = parsed > 0;
        }
        std::vector<SectionSpec> sections(cameras.size(), default_section);
        std::vector<char> sectioned(cameras.size(), has_default_section ? 1 : 0);
        if (params.contains("sections") && !params.at("sections").is_null()) {
            const json& per = params.at("sections");
            if (!per.is_array() || per.size() != cameras.size())
                return refuse("sections_invalid",
                              "sections must be an array the same length as cameras");
            for (size_t i = 0; i < per.size(); ++i) {
                SectionSpec spec;
                const int parsed = parse_section_spec(per[i], spec, reason);
                if (parsed < 0)
                    return refuse("section_invalid",
                                  "sections[" + std::to_string(i) + "]: " + reason);
                sectioned[i] = parsed > 0 ? 1 : 0;
                if (parsed > 0) sections[i] = spec;
            }
        }

        // Tessellate + flatten under the doc lock, then measure without holding it: the scene
        // is a private copy, so a 170-camera batch never blocks the document.
        MetricsScene scene;
        long revision = 0;
        {
            DocLock lk;
            Session& s = require_session(doc_id);
            revision = s.revision;
            scene = build_metrics_scene(tessellate_session_bodies(s));
        }
        if (scene.tris.empty())
            return refuse("no_geometry", "document has no tessellated geometry to measure");

        std::vector<json> views(cameras.size());
        std::atomic<size_t> next{0};
        std::mutex error_mtx;
        std::exception_ptr error;
        size_t error_camera = 0;
        auto worker = [&] {
            MetricsBuffers buf;
            for (;;) {
                const size_t i = next.fetch_add(1);
                if (i >= cameras.size()) break;
                try {
                    views[i] = measure_view_metrics(scene, cameras[i],
                                                    sectioned[i] ? &sections[i] : nullptr, W, H,
                                                    buf);
                } catch (...) {
                    std::lock_guard<std::mutex> g(error_mtx);
                    if (!error) {
                        error = std::current_exception();
                        error_camera = i;
                    }
                }
            }
        };
        const size_t threads = std::min<size_t>(
            chudware::governor::solver_threads(), cameras.size());
        {
            std::vector<std::thread> pool;
            // A failed launch must join the workers already started before the scene,
            // buffers and error state unwind. Destroying a joinable thread terminates
            // the entire engine instead of reaching the metrics_failed boundary.
            struct JoinWorkers {
                std::vector<std::thread>& pool;
                std::atomic<size_t>& next;
                const size_t end;
                ~JoinWorkers() {
                    next.store(end);
                    for (std::thread& th : pool)
                        if (th.joinable()) th.join();
                }
            } join_workers{pool, next, cameras.size()};
            pool.reserve(threads - 1);
            for (size_t k = 1; k < threads; ++k) pool.emplace_back(worker);
            worker();
        }
        if (error) {
            try {
                std::rethrow_exception(error);
            } catch (const std::exception& e) {
                return refuse("metrics_failed",
                              "cameras[" + std::to_string(error_camera) + "]: " + e.what());
            } catch (...) {
                return refuse("metrics_failed",
                              "cameras[" + std::to_string(error_camera) + "]: view metrics exception");
            }
        }

        json faces = json::array();
        for (const MetricsFace& f : scene.faces)
            faces.push_back(json{
                {"body", f.body},
                {"face_id", f.face_id},
                {"surf_type", (int)f.surf_type},
                {"area_mm2", metrics_round(f.area, 1e4)},
                {"centroid", json::array({f.centroid.x, f.centroid.y, f.centroid.z})},
                {"normal", json::array({f.normal.x, f.normal.y, f.normal.z})},
                {"tri_count", f.tri_count}});
        json edges = json::array();
        for (const MetricsEdge& e : scene.edges)
            edges.push_back(json{{"body", e.body},
                                 {"edge_id", e.edge_id},
                                 {"curve_type", (int)e.curve_type},
                                 {"length_mm", metrics_round(e.length, 1e4)}});
        json views_json = json::array();
        for (json& v : views) views_json.push_back(std::move(v));
        const double timing_ms = std::chrono::duration<double, std::milli>(
                                     std::chrono::steady_clock::now() - t_start)
                                     .count();
        return json{{"ok", true},
                    {"revision", revision},
                    {"width", W},
                    {"height", H},
                    {"faces", std::move(faces)},
                    {"edges", std::move(edges)},
                    {"views", std::move(views_json)},
                    {"section", has_default_section ? section_spec_json(default_section)
                                                    : json(nullptr)},
                    {"timing_ms", metrics_round(timing_ms, 1e3)}};
    } catch (const OpError& e) {
        return json{{"ok", false}, {"error", e.what()}, {"code", e.code}, {"reason", e.what()}};
    } catch (const std::exception& e) {
        return refuse("metrics_failed", e.what());
    } catch (...) {
        return refuse("metrics_failed", "view metrics exception");
    }
}

// doc_render_contact_sheet (task 03): render SEVERAL views and tile them into one labelled PNG — the
// ideal multi-view self-check artifact. `views` is an array of specs (resolve_view_spec each);
// defaults to the six standard ortho views + iso when empty/omitted. Each tile carries its own
// header (view name + dims). Returns {ok, path, views:[names], cols, rows, tile:[w,h]}.
// `background` is an optional [r,g,b] (0-255) applied to every tile AND to the empty-tile
// fallback; the inter-tile gutters stay the fixed dark 30 grey that separates them.
json doc_render_contact_sheet(const std::string& doc_id, const std::string& out_path,
                              const nlohmann::json& views,
                              const nlohmann::json& background) {
    try {
        DocLock lk;
        Session& s = require_session(doc_id);
        std::vector<aicm::AicmBody> bodies = tessellate_session_bodies(s);
        if (bodies.empty()) return json{{"ok", false}, {"reason", "no bodies"}};

        std::vector<nlohmann::json> specs;
        if (views.is_array() && !views.empty())
            for (const auto& v : views) specs.push_back(v);
        else
            for (const char* n : {"front", "right", "top", "iso"})
                specs.push_back(std::string(n));

        std::vector<RenderLabel> labels = principal_face_labels(s);
        std::string dims = bbox_dims_label(bodies);
        const int TW = 384, TH = 300;  // per-tile size (contact-sheet tiles are a touch smaller)
        std::vector<std::vector<unsigned char>> tiles;
        std::vector<std::string> names;
        unsigned char bg[3];
        const bool has_bg = parse_render_background(background, bg);
        for (const auto& sp : specs) {
            ResolvedView rv = resolve_view_spec(sp);
            std::optional<ThicknessView> thickness;
            std::string thickness_reason;
            if (!parse_thickness_view(sp, thickness, thickness_reason))
                return json{{"ok", false}, {"code", "thickness_invalid"},
                            {"reason", thickness_reason}};
            std::vector<aicm::AicmBody> thickness_bodies;
            std::vector<std::vector<float>> thickness_colors;
            json thickness_echo;
            if (thickness)
                thickness_view_bodies(s, *thickness, thickness_bodies, thickness_colors,
                                      thickness_echo);
            std::string header =
                rv.name + (thickness ? "  " + thickness_header(*thickness)
                                     : (dims.empty() ? "" : "  " + dims));
            std::vector<unsigned char> img;
            if (!render_view_to_rgb(thickness ? thickness_bodies : bodies, labels, TW, TH, rv.dir,
                                    header, img,
                                    /*annotate=*/true, /*body_alpha=*/nullptr,
                                    /*frame_from=*/nullptr, /*min_painted=*/-1,
                                    /*focus=*/nullptr, /*out_frame=*/nullptr,
                                    /*perspective_camera=*/nullptr,
                                    has_bg ? bg : nullptr, /*section=*/nullptr,
                                    thickness ? &thickness_colors : nullptr)) {
                // blank tile rather than dropping the slot — in the caller's own background,
                // with a label that contrasts against it.
                img.resize((size_t)TW * TH * 3);
                for (size_t p = 0; p + 2 < img.size(); p += 3) {
                    img[p] = has_bg ? bg[0] : (unsigned char)245;
                    img[p + 1] = has_bg ? bg[1] : (unsigned char)245;
                    img[p + 2] = has_bg ? bg[2] : (unsigned char)245;
                }
                const bool dark_tile =
                    has_bg && (bg[0] * 299 + bg[1] * 587 + bg[2] * 114) / 1000 < 128;
                const unsigned char ink = dark_tile ? 220 : 60;
                blit_text(img, TW, TH, 6, 5, rv.name + " (EMPTY)", 2, ink, ink, ink);
            }
            tiles.push_back(std::move(img));
            names.push_back(rv.name);
        }
        if (tiles.empty()) return json{{"ok", false}, {"reason", "no views"}};

        int n = (int)tiles.size();
        int cols = (int)std::ceil(std::sqrt((double)n));
        int rows = (cols > 0) ? (n + cols - 1) / cols : 1;
        const int GAP = 4;
        int SW = cols * TW + (cols - 1) * GAP;
        int SH = rows * TH + (rows - 1) * GAP;
        std::vector<unsigned char> sheet((size_t)SW * SH * 3, 30);  // dark gutters between tiles
        for (int i = 0; i < n; ++i) {
            int cx = (i % cols) * (TW + GAP);
            int cy = (i / cols) * (TH + GAP);
            const std::vector<unsigned char>& t = tiles[i];
            for (int y = 0; y < TH; ++y) {
                size_t dst = ((size_t)(cy + y) * SW + cx) * 3;
                size_t src = (size_t)y * TW * 3;
                std::memcpy(&sheet[dst], &t[src], (size_t)TW * 3);
            }
        }
        std::string png = encode_png_rgb(SW, SH, sheet);
        std::ofstream f(out_path, std::ios::binary | std::ios::trunc);
        bool ok = (bool)f && (f.write(png.data(), (std::streamsize)png.size()), (bool)f);
        return json{{"ok", ok}, {"path", ok ? out_path : std::string()},
                    {"views", names}, {"cols", cols}, {"rows", rows},
                    {"tile", json::array({TW, TH})}};
    } catch (const OpError& e) {
        return json{{"ok", false}, {"error", e.what()}, {"code", e.code}};
    } catch (...) {
        return json{{"ok", false}, {"reason", "render exception"}};
    }
}

